with j as (select * from jsonb_to_recordset($law7d0034$[{"code_id":"BK_RF","article_number":"61.3","version_date":"1998-07-31","article_text":"1. В бюджеты городских округов с внутригородским делением подлежат зачислению налоговые доходы от следующих местных налогов,  установленных представительными органами городских округов с внутригородским делением в соответствии с законодательством Российской Федерации о налогах и сборах:\n\nземельного налога - по нормативу 100 процентов;\n\nналога на имущество физических лиц - по нормативу 100 процентов;\n\nтуристического налога - по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n2. В бюджеты городских округов с внутригородским делением подлежат з\n\nцем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  превышающей 3402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 20 миллионов рублей и составляющей не более 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двадцать пятом настоящего пункта) ,  - по нормативу 3 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  превышающей 9402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двадцать пятом настоящего пункта) ,  - по нормативу 3 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 6 статьи 210 Налогового кодекса Российской Федерации,  превышающей 2, 4 миллиона рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом и тридцать шестом статьи 50 настоящего Кодекса) ,  а также налога на доходы физических лиц,  взимаемого на территориях городских поселений,  в отношении доходов физических лиц,  не являющихся налоговыми резидентами Российской Федерации,  указанных в абзаце девятом пункта 3 статьи 224 Налогового кодекса Российской Федерации,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  - по нормативу 4 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  а также налога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце двадцать седьмом настоящего пункта) ,  - по нормативу 5 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  а также налога на доходы физических лиц,  взимаемого на территориях городских поселений,  в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  - по нормативу 4 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  взимаемого на территориях сел